package main

func Balanced(s string) (bool, int) {
	depth := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			depth--
			if depth < 0 {
				return false, i
			}
		}
	}
	if depth != 0 {
		return false, len(s) - 1
	}
	return true, -1
}
